1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { under } from '../../engine/checks/helpers/path-containment.mjs';
3	
4	// Shared helpers and the standard's path constants — spelled ONCE here so the
5	// checks, the manifest, and the barrier can't drift apart. The wiki set is
6	// STRUCTURAL, not configured: a wiki page is a README.md at depth >= 2 under
7	// product-wiki/, outside the two reserved subtrees (product-requirements/ — the
8	// human-reviewed sink — and sample-data/ — illustrative assets). No wikis
9	// manifest exists anywhere, so a renamed or newly added wiki folder is
10	// classified correctly with nothing to drift (folder-is-the-classifier).
11	export const PRODUCT_ROOT = 'product-wiki';
12	export const SINK_DIR = 'product-wiki/product-requirements';
13	export const SAMPLE_DATA_DIR = 'product-wiki/sample-data';
14	export const INDEX_README = 'product-wiki/README.md';
15	export const SINK_README = 'product-wiki/product-requirements/README.md';
16	
17	export function wikiPages(files) {
18	  return files.filter(
19	    (f) => /^product-wiki\/.+\/README\.md$/.test(f) && !under(f, SINK_DIR) && !under(f, SAMPLE_DATA_DIR)
20	  );
21	}
22	
23	// One bullet/date grammar for every check that reads a growth log: a top-level
24	// bullet (-, * or + at column 0) leading with its YYYY-MM-DD run date, bold or
25	// plain — the invariant is dating, not typography. Date.UTC ROLLS OVER
26	// out-of-range parts (2026-02-30 → March 2) instead of failing, so calendar
27	// validity needs the explicit round-trip below.
28	export const BULLET = /^[-*+]\s/;
29	export const DATED = /^[-*+]\s+(?:\*\*)?(\d{4})-(\d{2})-(\d{2})(?:\*\*)?\b/;
30	export function realDateUTC(y, mo, d) {
31	  const dt = new Date(Date.UTC(y, mo - 1, d));
32	  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d
33	    ? dt.getTime() : null;
34	}
35	
36	// Blank out fenced code blocks, preserving line count — a template embedded in
37	// a ``` fence must neither satisfy a section requirement nor feed bullets into
38	// the section scans. Every section reader below works on the stripped text.
39	function stripFences(text) {
40	  let inFence = false;
41	  return text.split('\n').map((l) => {
42	    if (/^\s*(```|~~~)/.test(l)) { inFence = !inFence; return ''; }
43	    return inFence ? '' : l;
44	  });
45	}
46	
47	const headingRe = (name) => new RegExp(`^##\\s+${name}\\b`, 'i');
48	
49	// The heading text of the page's first real (non-fenced) `## ` section, or null
50	// when the page has none. The position half of the key-insights contract:
51	// "opens with" is checkable only as "no other `##` section precedes it" —
52	// the title and a sentence or two of framing prose before it are fine.
53	export function firstSection(text) {
54	  const line = stripFences(text).find((l) => /^##\s/.test(l));
55	  return line === undefined ? null : line.replace(/^##\s+/, '').trim();
56	}
57	
58	// Does the page carry a real (non-fenced) `## <name>` section heading?
59	// The single definition of the heading contract — sectionBody anchors on the
60	// same regex, so "present" and "readable" can never disagree.
61	export function hasSection(text, name) {
62	  const re = headingRe(name);
63	  return stripFences(text).some((l) => re.test(l));
64	}
65	
66	// The lines of the `## <name>` section (case-insensitive; suffix words after
67	// the name are fine — "## Open questions (for the next pass)") up to the next
68	// `## ` heading or EOF, fenced content blanked. Each entry carries its
69	// 1-indexed file line so findings can pin the offending bullet. Returns null
70	// when the heading is absent — callers skip then, because the missing heading
71	// is page-sections' finding (never double-report).
72	export function sectionBody(text, name) {
73	  const lines = stripFences(text);
74	  const re = headingRe(name);
75	  const start = lines.findIndex((l) => re.test(l));
76	  if (start === -1) return null;
77	  let end = lines.length;
78	  for (let i = start + 1; i < lines.length; i++) {
79	    if (/^##\s/.test(lines[i])) { end = i; break; }
80	  }
81	  return lines.slice(start + 1, end).map((t, i) => ({ line: start + 2 + i, text: t }));
82	}
83	
84	// The pack takes no config — the product-wiki/ layout IS the standard. A config
85	// object on the pack entry is a settings mistake (probably a misremembered
86	// knob), surfaced once, by the layout check only (no cascade). Deliberately
87	// pack-local rather than a runner-level manifest flag: no other pack rejects
88	// config yet, and a core seam for it can subsume this when a second pack needs
89	// one. Known limit: riding a rule means rules:{"product-wiki-layout":"off"}
90	// silences the guard along with the check.
91	export function configGuard(ctx, rule) {
92	  const cfg = ctx.config?.packConfig?.['product-wiki'];
93	  if (cfg === undefined || cfg === null) return [];
94	  return [finding(rule, {
95	    file: '.claudinite-checks.json',
96	    what: 'product-wiki config: the pack takes no config — the product-wiki/ layout is the standard',
97	    fix: 'remove the "config" object from the product-wiki pack entry (to silence the freshness advisory use rules: {"product-wiki-freshness": "off"})',
98	  })];
99	}
